import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"字体和调色板","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-dev-guide/user_interface_design/font_palette.md","filePath":"zh/qgc-dev-guide/user_interface_design/font_palette.md"}`),a={name:`zh/qgc-dev-guide/user_interface_design/font_palette.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="字体和调色板" tabindex="-1">字体和调色板 <a class="header-anchor" href="#字体和调色板" aria-label="Permalink to “字体和调色板”">​</a></h1><p>QGC有一套标准的字体和调色板，应该由所有用户界面使用。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import QGroundControl.Controls</span></span></code></pre></div><h2 id="qgcpalette-qgc调色板" tabindex="-1">QGCPalette(QGC调色板) <a class="header-anchor" href="#qgcpalette-qgc调色板" aria-label="Permalink to “QGCPalette(QGC调色板)”">​</a></h2><p>此项目显示QGC调色板。 这个调色板有两种变体：浅色和深色。 较浅的调色板适合户外使用，黑色调色板适用于室内。 通常，您不应该直接为UI指定颜色，您应该使用调色板中的颜色。 如果不遵循此规则，则您创建的用户界面将无法通过浅色/深色样式更改。 There are two variants of this palette: light and dark. The light palette is meant for outdoor use and the dark palette is for indoor. Normally you should never specify a color directly for UI, you should always use one from the palette. If you don&#39;t follow this rule, the user interface you create will not be capable of changing from a light/dark style.</p><h2 id="qgcmappalette-qgc地图调色板" tabindex="-1">QGCMapPalette(QGC地图调色板) <a class="header-anchor" href="#qgcmappalette-qgc地图调色板" aria-label="Permalink to “QGCMapPalette(QGC地图调色板)”">​</a></h2><p>The map palette is used for colors which are used to draw over a map. 地图调色板用于绘制地图的颜色。 由于不同的地图样式，特别是卫星和街道，您需要有不同的颜色来清晰地绘制它们。 卫星地图需要更浅的颜色，而街道地图需要更深的颜色。 QGCMapPalette项目为此提供了一组颜色，以及在地图上切换浅色和深色的功能。 Satellite maps needs lighter colors to be seen whereas street maps need darker colors to be seen. The <code>QGCMapPalette</code> item provides a set of colors for this as well as the ability to switch between light and dark colors over maps.</p><h2 id="screentools-屏幕工具" tabindex="-1">ScreenTools (屏幕工具) <a class="header-anchor" href="#screentools-屏幕工具" aria-label="Permalink to “ScreenTools (屏幕工具)”">​</a></h2><p>The ScreenTools item provides values which you can use to specify font sizing. ScreenTools项提供可用于指定字体大小的值。 它还提供有关屏幕大小以及QGC是否在移动设备上运行的信息。</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};